  {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "What is drone data collection for AI?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "It's the capture of aerial imagery, video, and 3D scans from UAVs to train and validate AI models. Payloads include RGB, thermal, multispectral, and LiDAR sensors, and flights are planned around the resolution the model needs rather than coverage alone."
        }
      },
      {
        "@type": "Question",
        "name": "What altitude should drone data be collected at for training?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Work backward from the minimum pixels you need on your smallest object. With a typical 1-inch 20 MP camera, a 30 cm object spans about 9 pixels at 120 m and about 18 pixels at 60 m. Your ML team's pixel requirement sets the maximum altitude."
        }
      },
      {
        "@type": "Question",
        "name": "Can drones fly beyond visual line of sight for data collection?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "In the U.S., BVLOS flights currently need case-by-case FAA approval. The FAA proposed a Part 108 BVLOS rule in August 2025, but as of late September 2026 it had not taken effect. Other countries follow their own aviation rules."
        }
      },
      {
        "@type": "Question",
        "name": "What sensors can you fly?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "RGB mapping cameras, radiometric thermal cameras, multispectral sensors, aerial LiDAR, and high-bitrate video, chosen by what the downstream model needs to learn."
        }
      },
      {
        "@type": "Question",
        "name": "How do you handle privacy with people in aerial imagery?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "We confirm site permissions before flights, plan routes to limit capture of people and private property, and blur or exclude faces and license plates according to your data policy before delivery."
        }
      },
      {
        "@type": "Question",
        "name": "Can aerial data help train ground robots?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes, as maps and priors. Aerial orthomosaics, elevation models, and 3D scans help outdoor robots plan routes and detect site changes. They don't replace ground-level data from the robot's own sensors, which we can also collect."
        }
      }
    ]
  }
